package opencodev2_test

// Tests for the generated interceptor plugin. The plugin runs inside the V2
// server and cannot be executed here, so its shape and wiring are checked on
// the generated file Provision writes: the V2 plugin form (a default export
// {id, setup} registering tool hooks; a V1-form plugin is dropped by V2), the
// dispatch tool it filters on, what it forwards, and the way it rejects or
// rewrites a call.

import (
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"testing"

	"mosaic-agent-test/internal/domain"
	"mosaic-agent-test/internal/harness/opencodev2"
)

// provisionInterceptor provisions req (no logger bundle) and returns the
// generated interceptor plugin's content.
func provisionInterceptor(t *testing.T, sb domain.Sandbox, req domain.ProvisionRequest) string {
	t.Helper()
	prov, err := opencodev2.New(opencodev2.Options{ScopeProbe: fixtureScopeProbe{}}).Provision(testContext(), req)
	if err != nil {
		t.Fatalf("Provision: %v", err)
	}
	path := filepath.Join(pluginsDir(sb), opencodev2.PluginFileName)
	if !contains(prov.Files, path) {
		t.Fatalf("Provisioning.Files = %v, want it to record the interceptor plugin %q", prov.Files, path)
	}
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("reading generated interceptor plugin: %v", err)
	}
	return string(data)
}

func generatedInterceptor(t *testing.T) (string, domain.Sandbox, domain.ProvisionRequest) {
	t.Helper()
	sb := newSandbox(t, t.TempDir())
	req := minimalProvisionRequest(sb)
	return provisionInterceptor(t, sb, req), sb, req
}

func TestGeneratedPlugin_IsAGeneratedFileWithThePluginFileName(t *testing.T) {
	content, _, _ := generatedInterceptor(t)

	if !strings.HasSuffix(opencodev2.PluginFileName, ".ts") {
		t.Errorf("PluginFileName = %q, want a .ts file name", opencodev2.PluginFileName)
	}
	first := strings.SplitN(content, "\n", 2)[0]
	if strings.TrimSpace(first) != "// Code generated by mosaic-agent-test. DO NOT EDIT." {
		t.Errorf("first line = %q, want the generated-code marker", first)
	}
}

func TestGeneratedPlugin_IsInV2FormDefaultExportWithIdAndSetup(t *testing.T) {
	content, _, _ := generatedInterceptor(t)

	if !regexp.MustCompile(`export\s+default`).MatchString(content) {
		t.Errorf("plugin has no default export; content=\n%s", content)
	}
	if !regexp.MustCompile(`id\s*:\s*["']mosaic-interceptor["']`).MatchString(content) {
		t.Errorf("plugin default export has no id \"mosaic-interceptor\"; content=\n%s", content)
	}
	if !regexp.MustCompile(`\bsetup\s*\(`).MatchString(content) && !regexp.MustCompile(`\bsetup\s*:`).MatchString(content) {
		t.Errorf("plugin default export has no setup; content=\n%s", content)
	}
}

func TestGeneratedPlugin_HasNoV1HookMapKeys(t *testing.T) {
	content, _, _ := generatedInterceptor(t)

	for _, v1Key := range []string{"tool.execute.before", "tool.execute.after"} {
		if strings.Contains(content, v1Key) {
			t.Errorf("plugin contains the V1 hook-map key %q; V2 drops a V1-form plugin", v1Key)
		}
	}
}

func TestGeneratedPlugin_RegistersBothToolHooksThroughTheHostContext(t *testing.T) {
	content, _, _ := generatedInterceptor(t)

	for _, hook := range []string{"execute.before", "execute.after"} {
		re := regexp.MustCompile(`tool\.hook\(\s*["']` + regexp.QuoteMeta(hook) + `["']`)
		if !re.MatchString(content) {
			t.Errorf("plugin does not register ctx.tool.hook(%q); content=\n%s", hook, content)
		}
	}
}

func TestGeneratedPlugin_ImportsOnlyNodeChildProcess(t *testing.T) {
	content, _, _ := generatedInterceptor(t)

	specifier := regexp.MustCompile(`(?:from\s+|import\s*\(\s*|require\s*\(\s*|import\s+)["']([^"']+)["']`)
	matches := specifier.FindAllStringSubmatch(content, -1)
	if len(matches) == 0 {
		t.Fatalf("plugin imports nothing; it must start the interceptor through node:child_process; content=\n%s", content)
	}
	for _, m := range matches {
		if m[1] != "node:child_process" {
			t.Errorf("plugin imports %q, want only node:child_process", m[1])
		}
	}
}

func TestGeneratedPlugin_NeverWritesToStdoutOrStderr(t *testing.T) {
	content, _, _ := generatedInterceptor(t)

	for _, banned := range []string{"console.log", "console.error", "console.warn", "console.info", "process.stdout", "process.stderr"} {
		if strings.Contains(content, banned) {
			t.Errorf("plugin uses %q; it must never write to the host's output", banned)
		}
	}
}

func TestGeneratedPlugin_IsDeterministic(t *testing.T) {
	first, sb, req := generatedInterceptor(t)

	sb2 := sb
	sb2.SubjectDir = filepath.Join(filepath.Dir(sb.SubjectDir), "subject-second")
	if err := os.MkdirAll(sb2.SubjectDir, 0o755); err != nil {
		t.Fatalf("creating second subject dir: %v", err)
	}
	req2 := req
	req2.Sandbox = sb2
	second := provisionInterceptor(t, sb2, req2)

	if first != second {
		t.Errorf("two provisions with identical bridges produced different plugin content")
	}
}

func TestGeneratedPlugin_ReflectsTheBridgeArguments(t *testing.T) {
	first, _, _ := generatedInterceptor(t)
	second, _, _ := generatedInterceptor(t)

	if first == second {
		t.Errorf("plugin content identical for two sandboxes with different control directories; the bridge arguments must be reflected")
	}
}

func TestProvision_InterceptorIsTheOnlyInputRewritingContribution(t *testing.T) {
	sb := newSandbox(t, t.TempDir())
	req := minimalProvisionRequest(sb)
	req.LoggerBundleDir = fixtureBundleDir(t, "fixture-bundle")

	prov, err := opencodev2.New(opencodev2.Options{ScopeProbe: fixtureScopeProbe{}}).Provision(testContext(), req)
	if err != nil {
		t.Fatalf("Provision with logger bundle: %v", err)
	}

	var interceptors int
	for _, f := range prov.Files {
		if filepath.Base(f) == opencodev2.PluginFileName {
			interceptors++
		}
	}
	if interceptors != 1 {
		t.Errorf("Provisioning.Files = %v, want exactly one %s", prov.Files, opencodev2.PluginFileName)
	}
	if _, err := os.Stat(filepath.Join(pluginsDir(sb), "mosaic-logger.ts")); err != nil {
		t.Errorf("logger entry missing next to the interceptor: %v", err)
	}
}

func TestProvision_InterceptorIsAtTheTopLevelOfThePluginsDirectory(t *testing.T) {
	_, sb, _ := generatedInterceptor(t)

	entries, err := os.ReadDir(pluginsDir(sb))
	if err != nil {
		t.Fatalf("reading plugins dir: %v", err)
	}
	var names []string
	for _, e := range entries {
		names = append(names, e.Name())
	}
	if !contains(names, opencodev2.PluginFileName) {
		t.Errorf("plugins directory holds %v, want %s at its top level (V2 loads only top-level files)", names, opencodev2.PluginFileName)
	}
}
